from pathlib import Path
import json,html
ROOT=Path(__file__).resolve().parent
data=json.loads((ROOT/'validation.json').read_text())['jobs']
titles={'00-fit-tests':'先打公／母试配片','01-upper-hopper':'上漏斗斗身','02-adapter-and-cameras':'上接座＋前后相机座','03-lower-collector':'下接豆斗','04-servo-cradle':'MG996R舵机架','05-limits-and-flag':'两限位座＋闸片旗片'}
notes={'00-fit-tests':'2只小试片，先确认插接；跨机器时交叉试配。','01-upper-hopper':'1件，大口法兰贴床，无支撑。','02-adapter-and-cameras':'3件，底面贴床，无支撑；实物孔距先核纸样。','03-lower-collector':'1件，小口贴床；支撑仅位于豆路外侧。','04-servo-cradle':'1件，6道墙／40%填充，清掉安装耳承梁下支撑。','05-limits-and-flag':'3件，限位座侧放，无支撑。'}
cards=''.join(f'<article><img src="thumbnails/{jid}.png" alt="{titles[jid]}的实际切片模型缩略图"><div class="body"><small>{jid}</small><h2>{title}</h2><p>{notes[jid]}</p><p class="estimate" data-job="{jid}"></p><a class="download" data-job="{jid}" download>下载对应机型打印文件 ↗</a></div></article>' for jid,title in titles.items())
doc='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BeanLens · 拓竹打印清单</title><link rel="icon" href="data:,"><style>*{box-sizing:border-box}body{margin:0;background:#f3f5f3;color:#25372d;font:16px/1.65 system-ui,-apple-system,sans-serif}header,main,footer{max-width:1200px;margin:auto;padding:26px}header{padding-top:40px}h1{font-size:30px;line-height:1.3;margin:8px 0 16px}h2{font-size:21px;margin:5px 0 12px}p{margin:8px 0}a{color:#216543}small,.muted{color:#607369}.top{display:flex;gap:16px;flex-wrap:wrap}.plan{padding:18px 22px;border:1px solid #cfddd1;background:white;border-radius:10px;margin:20px 0}.selector{display:flex;gap:10px;flex-wrap:wrap;margin:22px 0}button{font:inherit;border:1px solid #becfc2;background:white;color:#34513e;border-radius:7px;padding:9px 18px;cursor:pointer}button[aria-pressed=true]{background:#285f43;color:white;border-color:#285f43}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}article{min-width:0;background:white;border:1px solid #d4ded6;border-radius:12px;overflow:hidden}article img{width:100%;display:block;background:#e1e8df;aspect-ratio:1;object-fit:contain}.body{padding:18px}.body small{font-size:12px;overflow-wrap:anywhere}.body p{font-size:14px;min-height:46px}.body .estimate{font-weight:600;min-height:0;color:#2c573f}.download{display:block;background:#285f43;color:white;text-align:center;text-decoration:none;padding:11px;border-radius:7px;font-size:14px}footer{font-size:13px;color:#607369;padding-bottom:40px}.notice{border-left:4px solid #bd9957;padding:10px 16px;background:#faf5e9}code{font-size:14px}@media(max-width:850px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}header,main,footer{padding:18px}}@media(max-width:540px){.grid{grid-template-columns:minmax(0,1fr)}h1{font-size:25px}button{padding:8px 12px}}</style>
<header><small>BEANLENS ／ H3-BAMBU-P3 ／ 2026.10.22</small><h1>选对机器，再按盘打印。</h1><p>0.4mm标准喷嘴 · 拓竹PETG HF · 纹理PEI板 · 已实际切片</p><p class="muted">整套9件主零件＋1对试片。每种机型都有6盘可选，不要把五套全部打印。</p><div class="top"><a href="README.md">打印与装配说明</a><a href="print-jobs.csv">排产CSV</a><a href="validation.json">检查记录</a><a href="BeanLens-H3-Bambu-P3-20261022.zip">完整打印包ZIP</a></div><div class="plan"><b>赶比赛：四台并行</b><p>P2S：试片／上斗　·　X1 Carbon：试片／接座与相机座<br>X2D：下斗　·　A1：舵机架／限位与旗片　·　H2D备用</p><small>上斗与接座跨机时，两台分别先打00并交叉试插。约4小时量级的打印预算，不含烘料、冷却、拆撑和装配。只开两台的排法见说明。</small></div><p class="notice">主机切片检查通过，尚未实打。先核实机型和料盘，打印00试片；设备／板材／喷嘴不同则重新切片。</p></header>
<main><h2>选择要使用的机器</h2><div class="selector" role="group" aria-label="打印机选择">__BUTTONS__</div><p id="selected" aria-live="polite"></p><div class="grid">__CARDS__</div></main><footer>时长与用料为Bambu Studio 02.08.02.61估算。缩略图来自实际导出的切片文件，颜色仅作显示；发送时映射实装PETG HF。未修改原P1／P2装配尺寸；P2铝板、承托片及后横梁修订仍需实施。</footer>
<script>const JOBS=__DATA__,LABELS={P2S:'P2S',A1:'A1',X1C:'X1 Carbon',X2D:'X2D',H2D:'H2D'};let selected='P2S';function refresh(){document.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.machine===selected)));document.querySelector('#selected').textContent='当前下载文件均适用于 '+LABELS[selected]+' · 0.4mm · PETG HF · 纹理PEI';for(const r of JOBS.filter(r=>r.machine===selected)){const m=Math.round(r.estimated_seconds/60),text=(m>=60?Math.floor(m/60)+'小时':'')+(m%60)+'分 · '+r.estimated_g.toFixed(1)+'g';document.querySelector('.estimate[data-job="'+r.job+'"]').textContent=text;const a=document.querySelector('.download[data-job="'+r.job+'"]');a.href=r.file;a.textContent='下载 '+LABELS[selected]+' 已切片文件 ↗';}}document.querySelectorAll('button').forEach(b=>b.onclick=()=>{selected=b.dataset.machine;refresh();});refresh();window.printJobsStatus=()=>({machine:selected,links:[...document.querySelectorAll('.download')].map(a=>a.getAttribute('href'))});</script></html>'''
buttons=''.join(f'<button data-machine="{code}" aria-pressed="false">{label}</button>' for code,label in [('P2S','P2S'),('A1','A1'),('X1C','X1 Carbon'),('X2D','X2D'),('H2D','H2D')])
(ROOT/'index.html').write_text(doc.replace('__BUTTONS__',buttons).replace('__CARDS__',cards).replace('__DATA__',json.dumps(data,ensure_ascii=False)))
print('Offline print dashboard generated')
